def round_robin(processes, time_quantum):
    time = 0
    while processes:
        process = processes.pop(0)
        run_time = min(process.remaining_time, time_quantum)
        process.remaining_time -= run_time
        time += run_time
        if process.remaining_time > 0:
            processes.append(process)
    return time

