def round_robin_scheduling(burst_times, time_quantum):
    time = 0
    while burst_times:
        for i in range(len(burst_times)):
            if burst_times[i] > 0:
                run_time = min(burst_times[i], time_quantum)
                burst_times[i] -= run_time
                time += run_time
                if burst_times[i] <= 0:
                    del burst_times[i]
                    break
    return time

