def memory_cache(requests, cache_size):
    cache = {}
    page_faults = 0
    for page in requests:
        if page not in cache:
            page_faults += 1
            if len(cache) >= cache_size:
                cache.pop(next(iter(cache)))  # LRU replacement
            cache[page] = True
    return page_faults

def simulate_fifo(tasks):
    total_time = wait_time = 0
    for task in tasks:
        total_time += task
        wait_time += total_time - task
    avg_wait_time = wait_time / len(tasks)
    return {'total_time': total_time, 'avg_wait_time': avg_wait_time}

